    if(e.stunned>0)e.stunned-=sp;
    if(e._hitStun>0)e._hitStun-=sp;
    if(e.stunned<=0&&e._maxStunned){e._maxStunned=0;if(e.ib){_poiseReset(e);e._pImmune=Math.max(e._pImmune||0,300);e.s='idle';e.st2=30;e._teleDropY=0;}}
if(e._hitStun>0)return; // 피격 경직: AI 스킵
if(e.stunned>0){
  _cancelProjCharge(e);
  // 스턴 캡: 보스 3초(180f), 일반 3초(180f)
  if(e.stunned>180) e.stunned=180;
  // _maxStunned = 최초 스턴 시간 (게이지 비율 계산용)
  if(!e._maxStunned || e._maxStunned < e.stunned) e._maxStunned = e.stunned;
  // stunned 감소는 루프 초반(22509)에서 이미 처리됨
  // 스턴 종료 체크
  if(e.stunned <= 0){
    e.stunned = 0;
    e._maxStunned = 0;
    _poiseReset(e); // 포이즈 풀 회복
    if(e.ib){
      e._pImmune = Math.max(e._pImmune||0, 300); // 보스: 5초 면역
      e.s = 'idle'; e.st2 = 30; // 그로기 해제 → idle 강제 (패턴 중단)
      e._teleDropY = 0; // 텔레포트 낙하 리셋
    }
  }
  return;
}
if(!e.ib && e.poise < e.maxPoise){
  e.poiseR += sp;
  if(e.poiseR >= 200){ e.poise = Math.min(e.maxPoise, e.poise + ~~(e.maxPoise * 0.15)); e.poiseR = 0; }
}
